Here is the source code:
<source_code>
#include <bits/stdc++.h>
using namespace std;

long long solve(long long n) {
    if (n == 0) return 0;

    vector<long long> dp(n + 1, 0);
    dp[0] = 0;

    for (long long i = 1; i <= n; i++) {
        long long x = 1;
        long long count = 1;
        dp[i] = i; // worst case: use 1+1+...+1 (i times)

        while (x <= i) {
            long long diff = i - x;
            dp[i] = min(dp[i], count + dp[diff]);
            x = x * 10 + 1;
            count++;
        }

        // Also consider using a number with one more digit (like 111...1) and subtracting
        x = x / 10; // go back to previous x
        count--;
        if (x > 0) {
            long long next_x = x * 10 + 1;
            if (next_x <= 2 * i) { // only consider if it's not too far
                dp[i] = min(dp[i], count + 1 + dp[next_x - i]);
            }
        }
    }

    return dp[n];
}

int main() {
    ios_base::sync_with_stdio(false);
    long long n;
    cin >> n;
    cout << solve(n);
    return 0;
}
